A first look at a 3D city: the real buildings, roads and parks around Kaohsiung and Taichung Stations, with TRA trains on the viaduct at Taichung. It is a sample scene, not your own game, and needs the internet. Drag to move, pinch to zoom, two fingers to turn.	3D都市のお試し版：高雄駅と台中駅周辺の実在の建物・道路・公園と、台中の高架を走る台鉄の列車。あなたのゲームではないサンプル画面で、インターネット接続が必要です。ドラッグで移動、ピンチで拡大縮小、2本指で回転。
A freight line already brings materials here; more trains on it bring more.	貨物路線がすでに建材を運んでいます。列車を増やせばもっと届きます。
A freight yard takes the cargo the industrial land within {0} m makes, and holds it until a train of a freight line loads it. Trains let their cargo off at the next yard and are paid by the ton and the kilometre.	貨物ヤードは{0} m以内の工業用地が生む貨物を受け取り、貨物路線の列車が積むまで保管します。列車は次のヤードで貨物を降ろし、トン数と距離に応じて運賃を受け取ります。
A friend who opens it can start a game from your network or just look round it.	受け取った友人は、あなたの路線網からゲームを始めたり、眺めたりできます。
A friend's network you are only looking at is not saved. Open the file again and start a new game from it to keep it.	見ているだけの友達の路線網は保存されません。残すには、ファイルをもう一度開き、そこからニューゲームを始めてください。
A game keeps its rules to the end.	ルールは最後まで変更できません。
A guideway and other track can't cross on the level. Make this stretch elevated or a tunnel to pass over or under it.	軌道桁と他の線路は平面交差できません。この区間を高架かトンネルにして、上か下を越えてください。
A line calls at two stations or more, and not at the same station twice in a row. A ring calls at three or more, and not at the same station first and last.	路線は2駅以上に停車し、同じ駅に続けて停車できません。環状線は3駅以上に停車し、最初と最後を同じ駅にできません。
A line code is one to three letters A–Z or digits.	路線記号はA–Zの英字か数字で1〜3文字です。
A line keeps its trains at this depot: untick it on that line's depots first.	路線がこの車両基地に列車を置いています：先にその路線の車両基地でチェックを外してください。
A line needs two stations. Add another along your track under Build.	路線には駅が2つ必要です。「建設」で線路沿いにもう1つ置いてください。
A line needs two stations. Tap Build, then Station, then your track.	路線には駅が2つ必要です。「建設」→「駅」の順にタップし、線路をタップしてください。
A line opens between 00:00 and 23:59 and closes after it opens, by 06:00 the next morning.	路線の運行開始は00:00〜23:59で、終了は開始より後、翌朝06:00までです。
A line runs between stations. Lay track under Build, then put a station at each end.	路線は駅と駅の間を走ります。「建設」で線路を敷き、両端に駅を置いてください。
A line runs from 0 to 1,000 trains at each level.	路線の各時間帯の列車数は0〜1,000本です。
A line's chosen path runs along that track. Clear the line's path first.	路線の指定経路がその線路を通っています。先に路線の経路を解除してください。
A loop outside each track and a platform between each loop and its track, so fast trains can pass stopping ones.	各線の外側に待避線を設け、待避線と本線の間にホーム。速い列車が各停を追い越せます。
A managed company's city sets each station's ridership. Only free play can change it.	経営モードでは各駅の利用者数を都市が決めます。フリープレイでのみ変更できます。
A managed company's ridership comes from the land round its stations.	経営モードの利用者は駅周辺の土地から生まれます。
A map {0} by {1} is not supported.	{0}×{1}の地図には対応していません。
A melody needs at least one note, and at most {0}.	メロディは1音以上、{0}音までです。
A mission each week: finish it within its week for its badge. Badges stay on this device, in every game.	毎週1つのミッション：その週のうちに達成するとバッジを獲得。バッジはこの端末のすべてのゲームに残ります。
A name for this save, to find it in Saves.	「セーブデータ」で探しやすいよう名前を付けます。
A new fleet costs {0}; the old aircraft are not paid back.	新しい機材は{0}です。古い機材は返金されません。
A new language shows the next time the game opens.	新しい言語は次にゲームを開いたときに反映されます。
A new map each time.	毎回新しい地図。
A new stretch of track	新しい線路区間
A new train joined the fleet: {0}	新型車両が仲間入り：{0}
A passing loop and a signal station here. Lines that stop there can pass each other.	ここに待避線と信号場。そこに停まる路線は行き違いができます。
A passing loop lets them pass halfway. In Network, choose Loop and tap the single track: it adds a second track there with a signal station.	待避線があれば途中で行き違えます。「路線網」で「待避線」を選んで単線をタップすると、2本目の線路と信号場が加わります。
A path through the game for your first days. Each step is ticked as soon as it is done.	最初の数日の進め方です。各ステップは達成するとすぐにチェックが付きます。
A pattern calls at two of its line's stops or more, in the line's order. A ring has no patterns.	停車パターンは路線の順に、路線の2駅以上に停車します。環状線には停車パターンがありません。
A pier goes on the shore, right beside the water.	桟橋は岸の、水際のすぐ横に置きます。
A pier stands on the shore, marked pale blue: the nearest is about {0} m {1}.	桟橋は岸（水色のマス）に置きます：最寄りは{1}へ約{0} mです。
A platform already stands on part of this stretch: tap the track beside it.	この区間の一部にすでにホームがあります：隣の線路をタップしてください。
A platform is here: tap beside it	ホームがあります：隣をタップ
A platform is in the way	ホームが邪魔
A platform must lie on a level stretch of a single track and not overlap another platform.	ホームは単線の平坦な区間に置き、他のホームと重ならないようにしてください。
A platform outside each of the two tracks.	2線の外側にそれぞれホーム。
A platform track goes beside level track only.	ホーム用の線路は平坦な線路の横にしか置けません。
A platform track runs beside the platform with a turnout at each end. Island: one platform between the tracks, 11 m apart. Side: a platform outside each track, 5 m apart.	ホームの線路はホームの横に敷かれ、両端に分岐器が付きます。島式：線路間に1面のホーム、線路間隔11 m。相対式：各線路の外側にホーム、線路間隔5 m。
A population of {0}	人口{0}人
A quiet month: little changed	穏やかな月：変化はわずか
A random map each game.	毎回ランダムな地図。
A real station your trains carried passengers at gets its stamp the next day. Kept on this device.	列車が乗客を運んだ実在の駅には、翌日スタンプが押されます。この端末に記録されます。
A record day for the railway	鉄道の1日最多記録
A report on the year only: it gives and takes no money.	この1年の成績表です。お金の増減はありません。
A road already reaches this station.	この駅にはすでに道路がつながっています。
A road can't be built on this steep slope.	この急斜面には道路を敷けません。
A road can't go here: water or a slope too steep.	ここには道路を敷けません：水面か急すぎる斜面です。
A road now reaches {0}, for {1}.	{0}に道路が通じました（{1}）。
A route flies its real flights; you choose how many and how big the aircraft are. Airports stay the city's: each landing pays the airport a fee.	航空路線は実在の便を運航し、便数と機材の大きさを選べます。空港は都市のもので、着陸ごとに空港へ料金を払います。
A save exported from this or another device. It opens as soon as it is read.	この端末や他の端末から書き出したセーブデータです。読み込むとすぐに開きます。
A save was changed on this device and another, so both are kept: “{0}” is the other device's.	この端末と他の端末で同じセーブデータが変更されたため、両方を残しました：「{0}」が他の端末のものです。
A second track joins the line at each end, with one platform between the two, so trains can pass here.	両端で2本目の線路が合流し、間にホーム1面。ここで列車が行き違えます。
A sightseeing train calls here (+{0})	観光列車が停車（+{0}）
A small terminal with its tower on the roof, beside a short runway	屋上に管制塔がある小さなターミナルと短い滑走路
A span is longer than {0} km: add a stop between.	{0} kmを超える区間があります：間に駅を追加してください。
A station cannot be linked with itself.	駅を自分自身と結ぶことはできません。
A station for {0}	{0}に駅を
A station has a platform on that track. Remove the platform first: in Network, choose Remove, tap that track and tap “Remove platform”.	その線路に駅のホームがあります。先にホームを撤去してください：「路線網」で「撤去」を選び、その線路をタップして「ホームを撤去」をタップします。
A station starts 0 to {0} trips a day.	駅の1日の旅客数は0〜{0}です。
A station two lines share	2路線が停まる駅
A target headway must be between 2 minutes and 24 hours.	目標の運転間隔は2分〜24時間です。
A terminal with four boarding bridges, a control tower and a hangar	搭乗橋4基のターミナル、管制塔、格納庫
A tile of the map can be bought for {0}. Open Expand on the map.	地図1区画を{0}で購入できます。地図の「拡張」を開いてください。
A timetable's times cannot be negative or go back: each stop leaves no earlier than it arrives, and no later than the next stop arrives. A repeating timetable needs a stop, and a period long enough to start again without going back.	時刻表の時刻は負にも逆戻りにもできません：各駅の発車は到着より早くなく、次の駅の到着より遅くできません。繰り返す時刻表には停車駅が1つ以上必要で、逆戻りせずに再開できる長さの周期が必要です。
A timetable's trains each run between two of the line's stops at times that never go back. A ring, a line with patterns or one calling at a station twice has no timetable.	時刻表の各列車は路線の2駅間を、逆戻りしない時刻で走ります。環状線、停車パターンのある路線、同じ駅に2回停まる路線には時刻表がありません。
A town of about {0} people has no station	約{0}人の町に駅がありません
A train	1編成
A train can only be placed on the track, with track behind it for all its cars.	列車は線路上にのみ置けます。後方に全車両分の線路が必要です。
A train every	運転間隔
A train every {0} min	{0}分間隔に
A train has {0} to {1} cars.	列車は{0}〜{1}両です。
A train is coming: wait for it	列車が接近中：通過を待つ
A train is on that track now. Tap again once it has passed.	今その線路に列車がいます。通過後にもう一度タップしてください。
A train is on that track. Take the train off the track first.	その線路に列車がいます。先に列車を線路から外してください。
A train of {0} is waiting for another on single track: only one can use it at a time.	{0}の列車が単線で別の列車を待っています：単線は一度に1本しか使えません。
A train stays at a stop {0} s to {1} min.	停車時間は{0}秒〜{1}分です。
A train waiting to turn back at the end of its line stands inside the platform, not a car past it.	終点で折り返しを待つ列車は、1両はみ出さずにホーム内に停まります。
A train was full yesterday ({0}%). Add a train or longer trains so nobody is left behind.	昨日、満員の列車がありました（{0}%）。積み残しが出ないよう、列車を増やすか長くしてください。
A train was over full	定員超過の列車あり
A train's rate cannot be negative.	列車のレートは負にできません。
A train's route runs over that track. Wait for it to pass.	列車の進路がその線路を通ります。通過を待ってください。
A turnout can stand on a grade of at most 25 in 1000, and this track is steeper. Start from its end, or from gentler track.	分岐器は25‰以下の勾配にしか置けず、この線路はそれより急です。線路の端か、緩やかな線路から始めてください。
A turnout can't stand where the track's grade is changing, near this end of the slope. Pick a point farther along, or start from its end.	勾配が変わる場所、この坂の端の近くには分岐器を置けません。もっと先の地点を選ぶか、坂の端から始めてください。
A typhoon blows over it today	今日は台風が通過中です
A typhoon comes in {0} day{1}, over {2} of our stations: about {3}% fewer passengers there. Run fewer trains, or close those stations for it.	{0}日後に台風が来て、当社の{2}駅を通過します：そこでの乗客は約{3}%減ります。減便するか、その駅を閉鎖しましょう。
A typhoon is blowing over {0} of our stations, about {1}% fewer passengers there.	台風が当社の{0}駅を通過中で、そこでの乗客は約{1}%減っています。
A typhoon is blowing over {0} of our stations: about {1}% fewer passengers there today.	台風が当社の{0}駅を通過中です：今日はそこでの乗客が約{1}%減ります。
A typhoon is blowing; it misses our stations.	台風が来ていますが、当社の駅には影響しません。
A viaduct or bridge stands at most 64 m above the ground.	高架と橋は地面から最大64 mです。
A wharf or a marina goes on the shore, part over the water.	埠頭やマリーナは岸に、一部を水上にかけて建てます。
A year closes every 360 days.	360日ごとに年度を締めます。
