How many people use each station of the TRA, the High Speed Rail, Taipei Metro, New Taipei Metro’s four lines, the Taoyuan Airport MRT, Taichung Metro and Kaohsiung Metro’s Red and Orange Lines a day: build a station beside one, and riders change to it in proportion.	台鉄、高鉄、台北MRT、新北MRTの4路線、桃園空港MRT、台中MRT、高雄MRT紅線・橘線の各駅の1日の利用者数：その近くに駅を建てると、人数に応じて乗客が乗り換えてきます。
How many storeys the real buildings of 3D maps in Taiwan have, from Taichung’s building map, Taipei’s building permit map the usage permits of New Taipei, Taipei, Tainan and Hsinchu City and the real-price registry of home sales, and elsewhere how tall the buildings round them are. In Taichung the buildings’ outlines are the building map’s too. Where the map has no building, the homes sold in the real-price registry stand along the roads with their own storeys.	台湾の実在の3D地図にある実際の建物の階数。台中市建物図、台北市建築執照套絵図、新北市・台北市・台南市・新竹市の使用執照、不動産取引の実価登録によります。それ以外の場所は周囲の建物の高さから決めます。台中市では建物の形も台中市建物図によります。地図に建物がない場所では、実価登録で売買された住宅をその階数で道路沿いに建てます。
How many trips in each county and city of Taiwan are made by scooter or car: on a real-world map, when your trains are slower, at most that share of your riders ride or drive instead.	台湾の各県市で、移動のうちオートバイや自動車によるものの割合：実在の地図で列車が遅いと、最大でその割合の利用者がオートバイや自動車に切り替えます。
How many visitors each of Taiwan's main sights has in a year, shown on its card in the sights panel.	台湾の主な観光地の年間来訪者数。観光地パネルの各カードに表示します。
How much of the ground real buildings cover on real-world maps of Taiwan and Penghu, which sets what buying out the city’s buildings costs: a car park costs little, a dense block a lot. The buildings of 3D maps in Taiwan, Penghu, Kinmen and Matsu, and of the 3D city preview round Kaohsiung and Taichung Stations, are its too, but in Taichung City, where the city’s own building map draws them.	台湾と澎湖の実在の地図で実際の建物が地面を覆う割合。都市の建物の買収費用を決めます：駐車場は安く、密集した街区は高くなります。台湾・澎湖・金門・馬祖の3D地図の建物と、3D都市プレビューの高雄駅・台中駅周辺の建物もこのデータです（台中市内は市の建物図によります）。
