Tap or drag: growing stations build {0} on empty zoned cells first, those worth most first. Zoned cells near your buildings are worth more.	タップかドラッグ：成長中の駅が空いた指定マスに{0}を建てます。価値の高いマスから順に建てます。自分の建物の近くのマスほど価値が上がります。
Tap roads for its other stops, in the order the bus calls. Tap a stop again to take it away.	バスが停まる順に道路をタップして停留所を置きます。もう一度タップすると外れます。
