The Airport MRT from Taipei Main Station to Laojie River, with its commuter and express trains at their real times.	台北駅〜老街渓間の空港MRT。普通車と直達車が実際の時刻で走ります。
The Christmas livery is yours to keep.	クリスマス塗装はずっと使えます。
The English line and station names are compiled by {0}.	英語の路線名と駅名は{0}がまとめたものです。
The Fukuoka City Subway’s three lines, the Kuko, Hakozaki and Nanakuma lines, with their stations’ names in Chinese, English and Japanese. There is no published timetable, so their trains run at estimated intervals.	福岡市地下鉄の空港線・箱崎線・七隈線の3路線で、駅名は中国語・英語・日本語です。公開された時刻表がないため、列車は推定の運転間隔で走ります。
The Green Line (Wuri–Wenxin–Beitun) from Beitun Main Station to HSR Taichung Station.	北屯総站〜高鉄台中駅間の緑線（烏日文心北屯線）。
The High Speed Rail could not be built from the real-world data.	実地図データから高鉄を建設できませんでした。
The Japan map's introduction now tells of Fukuoka, Saga, Nagasaki and Kumamoto and the lines you can buy there.	日本地図の紹介文を、福岡・佐賀・長崎・熊本の4県と今買える路線の内容に書き直しました。
The Kumamoto City Tram's Lines A and B are on sale together on the Japan map: white and wine-red low-floor trams run to their real timetable from their own depots.	日本地図で熊本市電のA系統・B系統をまとめて買えます。白とワインレッドの超低床電車が、実際の時刻表どおりに自前の車庫から出庫します。
The Kumamoto City Tram’s Lines A and B, with their stops’ names in Chinese, English and Japanese and their trams’ real timetable.	熊本市電のA系統とB系統。電停名は中国語・英語・日本語で、電車は実際の時刻表どおりに走ります。
The Kyushu Shinkansen from Hakata to Kumamoto, with its seven stations’ names in Chinese, English and Japanese. Its trains call at every station, at estimated times.	博多〜熊本間の九州新幹線で、7駅の駅名は中国語・英語・日本語です。列車は各駅に停車し、推定の時刻で走ります。
The Kyushu Shinkansen goes on south from Kumamoto to Shin-Yatsushiro and Shin-Minamata on the Japan map; a game that already has Hakata to Kumamoto can buy the rest.	日本地図の九州新幹線が熊本から新八代・新水俣まで南へ延びました。博多〜熊本を買ってあるゲームでは残りを買い足せます。
The Main Line from Chiayi to Alishan and the Shenmu, Zhaoping and Zhushan Lines, in the Alishan Forest Railway’s red.	本線（嘉義〜阿里山）と神木線、沼平線、祝山線を、阿里山森林鉄道の赤で描きます。
The Nishi-Kyushu Shinkansen runs the N700S Kamome, and the suspended monorail has a new model.	西九州新幹線はN700S かもめになり、懸垂式モノレールは新しいモデルになりました。
The OSM base map of real-world maps in Taiwan (OSM in the map style menu), which works without a network: sea, rivers, woods, parks, roads, boundaries and place names. The 3D map lays its sea, rivers, woods, parks and roads on the ground.	台湾の実在の地図の OSM ベースマップ（地図スタイルメニューの「OSM」）。ネットワークなしで表示できます：海、川、森林、公園、道路、境界、地名。3D地図では、海、川、森林、公園、道路を地面に描きます。
The OSM base map of real-world maps outside Taiwan (OSM in the map style menu).	台湾以外の実在の地図の OSM ベースマップ（地図スタイルメニューの「OSM」）。
The Pingxi Line is ours now, built for coal and losing money. Reach {0} riders a day and a year's net profit of {1}. The Sky Lantern Festival brings crowds to Shifen and Pingxi: get trains ready for it!	平渓線は私たちの路線になりました。石炭輸送のために造られ、赤字が続いています。1日の利用者{0}人、年間純利益{1}を達成しましょう。天灯祭りには十分と平渓に人が押し寄せます。列車を備えておきましょう！
The Red Line, the Orange Line and the Circular Light Rail, each in its own colour.	紅線、橘線、環状ライトレール。各路線の色で描きます。
The Relay Kamome from Hakata to Takeo-Onsen is on sale on the Japan map, run by 885 and 787 series trains, and at Takeo-Onsen it meets the N700S Kamome across the platform.	日本地図でリレーかもめ（博多〜武雄温泉、885系・787系）を買えます。武雄温泉では同じホームの向かいでN700S かもめに乗り換えます。
The Sky Lantern Festival starts in {0} day{1}: {2}% more passengers at {3}. Add trains before it.	天燈祭りまであと{0}日：{3}で乗客が{2}%増えます。前もって増発しましょう。
The Taiwan High Speed Rail is for sale in a Taiwan game with realistic rules: buy it from Nangang to Zuoying with its viaducts, depots, land along the way and the real day of trains; it pays a monthly upkeep once bought.	リアルルールの台湾のゲームで台湾高速鉄道を買収できます。南港〜左営の高架橋、車両基地、沿線の土地、実際の1日分のダイヤをまとめて買い、以後は毎月維持費がかかります。
The Taiwan High Speed Rail you buy runs 700T trains, and on high-speed lines you build yourself every other train is an N700ST in Taiwan High Speed Rail colours.	買収した台湾高速鉄道はすべて700Tで走ります。自分で建設した高速線では、1本おきに台湾高速鉄道塗装のN700STが走ります。
The Train Pack’s high-speed train on the 3D map, white with two blue lines: a model the game’s author made.	トレインパックの3D地図の高速列車（白い車体に青い2本線）：ゲーム作者が作ったモデル。
The Wenhu, Tamsui–Xinyi (with the Xinbeitou branch), Songshan–Xindian (with the Xiaobitan branch), Zhonghe–Xinlu and Bannan Lines, each in its own colour.	文湖線、淡水信義線（新北投支線を含む）、松山新店線（小碧潭支線を含む）、中和新蘆線、板南線。各路線の色で描きます。
The Western Trunk, Mountain, Coast, Chengzhui, Pingtung, South-Link, Taitung, North-Link and Yilan Lines, and six branch lines: Pingxi, Shenao, Neiwan, Liujia, Jiji and Shalun, all in TRA blue. On a real-world map you can buy the six branch lines, and their trains keep TRA’s real times.	縦貫線、山線、海線、成追線、屏東線、南廻線、台東線、北廻線、宜蘭線と、平渓・深澳・内湾・六家・集集・沙崙の6支線。すべて台鉄ブルーで描きます。実在の地図ではこの6支線を購入でき、列車は台鉄の実際の時刻で走ります。
The Yilan Line could not be built from the real-world data.	実地図データから宜蘭線を建設できませんでした。
The air route is sold.	航空路線を売却しました。
The app no longer carries its maps: a map downloads the first time you open it (you need to be online), and Map in Settings can remove one or download it again.	地図はアプリに内蔵されなくなりました：初めて開くときに自動でダウンロードされます（ネット接続が必要）。設定の「地図」で削除や再ダウンロードができます。
The bands you split or changed go.	分割・変更した時間帯は削除されます。
The bank cannot make this term loan: check the amount, the term and how much it still lends.	銀行はこの定期借入に応じられません：金額、期間、残りの融資枠を確認してください。
The bank has nothing more to lend now. It lends more as the company is worth more.	今は銀行の融資枠がありません。会社の価値が上がると融資枠も増えます。
The bank holds {0} term loans at once. Repay one to sign another.	定期借入は同時に{0}件までです。1件返済すると新たに契約できます。
The base map and place search of real-world maps.	実在の地図のベースマップと場所検索。
The bell rings as trains arrive; the melody plays as the doors close on a train you are watching, at 60× or slower. Picking one plays it once, and the play buttons play it again.	列車の到着時にベルが鳴り、表示中の列車のドアが閉まるときにメロディが流れます（60倍速以下）。選ぶと一度再生され、再生ボタンでもう一度聞けます。
The bus route is closed.	バス路線を廃止しました。
The bus route to {0} is changed, for {1}.	{0}へのバス路線を変更しました（{1}）。
The cable car cannot go here.	ここにはロープウェイを造れません。
The cable car is taken down.	ロープウェイを撤去しました。
The camera follows its landing.	カメラが着陸を追います。
The card of the tutorial's last step no longer jumps back and forth.	チュートリアル最後のステップのカードが行ったり来たりしなくなりました。
The cells within 800 m of a station, and the cells with people that no station reaches.	駅から800 m以内のマスと、どの駅も届かない人がいるマスです。
The challenge ends in {0} day{1}.	チャレンジ終了まであと{0}日です。
The city	都市
The city builds nothing new here, and what stands here neither grows nor is raised.	都市はここに新しい建物を建てず、既存の建物も成長・建て替えしません。
The city buses on the 3D map’s streets: a model generated with Meshy’s AI from a description and a photograph. The evening garbage truck and recycling truck, the bus stop signs on the pavements, and the level crossings’ barriers and warning lights: models generated by AI from a description, simplified and in the game’s colours. The night markets’ strings of bulbs, striped canopies and snack carts, and the Tiangong burners and stone lions before the temples: models generated by AI from a description, simplified and in the game’s colours. The people on the platforms, streets and bus stops, seen close up, and the parked bicycles: AI-generated models, simplified and in the game’s colours. The Great Buddha of Baguashan in Changhua: a statue generated with Meshy’s AI, simplified and in the game’s colours.	3D地図の街を走る路線バス：Meshy のAIで説明文と写真から生成したモデル。夕方のごみ収集車と資源回収車、歩道のバス停標識、踏切の遮断機と警報灯：AIで説明文から生成し、簡略化してゲームの配色にしたモデル。夜市の電球の列、縞模様の日よけ、屋台、寺廟前の天公炉と石獅子：AIで説明文から生成し、簡略化してゲームの配色にしたモデル。近くで見たときのホーム・街・バス停の人と、駐輪中の自転車：AIで生成し、簡略化してゲームの配色にしたモデル。彰化の八卦山大仏：Meshy のAIで生成し、簡略化してゲームの配色にした像。
The city has {0} new request{1} for us, paying up to {2}. See Goals.	都市から新しい依頼が{0}件届きました（最高{2}）。「目標」を確認しましょう。
The city takes it over: its people stay.	都市が引き継ぎます：住民はそのままです。
The city trusts you with {0} request{1} at a time: finish one first.	都市の信頼で同時に受けられる依頼は{0}件までです：先に1件を完了してください。
The coaling stage with its conveyor in the old brick plants’ yards on the 3D map: a model the game’s author made.	3D地図の古いれんが工場の敷地にある、コンベヤ付きの給炭台：ゲーム作者が作ったモデル。
The company is in the red. Bring the balance back above zero before switching to free play, or start a new game.	会社は赤字です。フリープレイに切り替える前に残高を0以上に戻すか、ニューゲームを始めてください。
The company still has term loans, {0} with their interest. Free play never pays them, so repay them before switching.	会社にはまだ利息込みで{0}の定期借入があります。フリープレイでは返済されないため、切り替える前に返済してください。
The company still owes {0}. Free play pays no interest, so repay the loan before switching.	会社にはまだ{0}の借入金があります。フリープレイでは利息を払わないため、切り替える前に返済してください。
The conifers in the 3D map’s mountain woods, the bushes by the stations and the line, the tanks in the factory yards and the cars on the streets: Kenney’s models, reshaped and in the game’s colours.	3D地図の山林の針葉樹、駅前と沿線の植え込み、工場敷地のタンク、街の自動車：Kenney のモデルを形を変えてゲームの配色にしたもの。
The dataset	データセット
The day's service levels must start at 00:00 and change at later times within the day.	1日の運行区分は00:00から始め、同じ日のより後の時刻で切り替えてください。
The device is warm, so the game slows down for now.	端末が熱くなっているため、しばらく速度を落とします。
The ends are too close	両端が近すぎる
The ends' heights are too far apart	両端の高低差が大きすぎる
The engine of a diesel train you follow, idling, pulling away and coasting, which the game makes to sound like these recordings of a KiHa 40 series railcar in Japan.	追従中の気動車のエンジン音（アイドリング、発進、惰行）で、ゲームが日本のキハ40系気動車の次の録音に似せて作っています。
The event ends on 6 January. Here are the badges you earned.	イベントは1月6日に終了します。獲得したバッジはこちらです。
The ferry route is closed.	フェリー航路を廃止しました。
The file could not be written: {0}	ファイルを書き出せませんでした：{0}
The first ones arrived in Taiwan.	初編成が台湾に到着しました。
The first stretch is straight. Lay the next one from its end and it bends along.	最初の区間は直線です。その端から次を敷くと、なめらかに曲がります。
The fullest section is {0}% full	最も混む区間の乗車率 {0}%
The fullest train of a day leaves {0} full on average	1日で最も混む便の平均乗車率は{0}
The game as it is now is kept as an autosave, so you can come back to it.	現在のゲームは自動保存として残るので、あとで戻れます。
The game author’s own model from the game’s earlier version, in the game’s colours, used with the author’s permission.	ゲーム作者が旧バージョンのために作ったモデルを、ゲームの配色にして作者の許可を得て使用しています。
The game author’s own model, in the game’s colours, used with the author’s permission.	ゲーム作者が作ったモデルを、ゲームの配色にして作者の許可を得て使用しています。
The game author’s own models from the game’s earlier version, in the game’s colours, used with the author’s permission.	ゲーム作者が旧バージョンのために作ったモデルを、ゲームの配色にして作者の許可を得て使用しています。
The game is not affiliated with any of the operators above.	本ゲームは上記のいずれの事業者とも関係ありません。
The game is running at {0}, slower than {1}.	ゲームは{0}で動作しており、設定の{1}より遅くなっています。
The game pauses when a typhoon is announced, a goal is met, the cash goes below zero or a challenge has a week left. Every 30 days a monthly report compares the month with the one before; it is always kept in the news log.	台風の発表、目標の達成、現金のマイナス、チャレンジの残り1週間でゲームが一時停止します。30日ごとに月次レポートで前月と比較し、ニュースに必ず記録されます。
The game really runs {0} times real time, slower than its speed	ゲームは実時間の{0}倍で動作しており、設定速度に追いつきません
The game runs {0} times real time	ゲームは実時間の{0}倍で進みます
The game speaks Japanese: choose 日本語 under Language in Settings and it takes effect the next time the app opens; stations and lines on the Japan map show their Japanese names.	日本語で遊べます：設定の「言語」で日本語を選ぶと次回の起動から切り替わり、日本地図の駅名・路線名も日本語になります。
The game will be in {0} the next time it opens. {1}	次回起動時から{0}になります。{1}
The game will use the {0}'s language the next time it opens. {1}	次回起動時から{0}の言語を使います。{1}
The goal was not met in time. Try again?	期限内に目標を達成できませんでした。もう一度挑戦しますか？
The goods waiting there go with it.	そこで待っている貨物も失われます。
The ground there has not been read yet.	その場所の地面はまだ読み込まれていません。
The ground's height; hatching marks slopes steeper than 30%, where the city cannot build.	地面の標高です。斜線は30%を超える急斜面で、都市は開発できません。
The high-speed line’s 700T on the 3D map, white with an orange band, and the white and blue 700 Series in the garage: models the game’s author made.	3D地図の高鉄700T型（白い車体にオレンジの帯）と、車庫の白と青の700系：ゲーム作者が作ったモデル。
The hillside is too steep to build or zone on.	斜面が急すぎて、建設も用途地域の指定もできません。
The industry round it makes about {0} t a day.	周辺の工業が1日に約{0} tの貨物を生み出します。
The land this line crosses does not touch yours. Use Expand Map to buy up to the line first, then buy it.	この路線が通る土地は自分の土地と接していません。「地図を拡張」で路線まで買い広げてから購入してください。
The last stop must be a station, not an angle station.	最後の駅は駅にしてください。角度変更所にはできません。
The letters of the station names on the platforms' name boards in the 3D map.	3D地図のホームの駅名標に使う文字。
The lie of the land on Taiwan’s main island, the islets beside it and Kinmen: how high the ground is on real-world maps, the hillsides steeper than 30 % where nothing new can be built, and the shaded hills of Taiwan’s OSM base map.	台湾本島、周辺の小島、金門の地形：実在の地図の地面の高さ、新たに建設できない勾配30%超の斜面、台湾 OSM ベースマップの陰影起伏。
The lie of the land where Taiwan’s own terrain model does not reach: Penghu, Matsu, Green Island and a patch of the mountains of Miaoli.	台湾の地形モデルが含まない地域の地形：澎湖、馬祖、緑島、苗栗の山地の一部。
The line from Nangang to Zuoying and its 12 stations, in the High Speed Rail’s orange. The High-Speed Rail Demo and Real Trains run to its real timetable of 29 September 2026, and the demo charges its real fares.	南港〜左営間の高鉄の路線と12駅を、高鉄オレンジで描きます。高速鉄道デモと実在の列車は2026年9月29日の実際の時刻表で走り、デモでは実際の運賃がかかります。
The line from Rovaniemi to Misi and Kemijärvi, and the main line south to Muurola, with every passenger train of a week in December at its real times.	ロヴァニエミからミシを経てケミヤルヴィへの路線と、南のムーロラへの本線。12月の1週間の旅客列車すべてが実際の時刻で走ります。
The line from {0} to {1} is ready. Check its stops and create it.	{0}〜{1}の路線を用意しました。停車駅を確認して作成してください。
The line has changed since the card opened: open it again for its price now.	カードを開いた後に路線が変わりました：開き直して現在の価格を確認してください。
The line has no pattern #{0}.	この路線に停車パターン #{0} はありません。
The line has no trains.	この路線には列車がありません。
The line is set to run {0} {1} at this time of day	この時間帯の運行は{0}本の設定です
The line runs only {0} {1} now (headway or track limits it)	現在の運行は{0}本のみ（運転間隔か線路による制限）
The line runs only {0} {1} now: run {2}	現在の運行は{0}本のみ：{2}本運行にする
The line starts at {0}. Tap its last station on the map.	路線は{0}から始まります。地図で最後の駅をタップしてください。
The main island and Penghu, about 286 by 390 km, all open from the start with no land to buy. Achievements and rankings do not count it. With a large network, older devices may slow down.	本島と澎湖、約286×390 km。最初からすべて開放され、土地の購入は不要です。実績とランキングの対象外です。路線網が大きいと古い端末では動作が遅くなることがあります。
The map doesn't reach that far north or south, so the square is as close to you as it goes. A map here stays this size.	地図はそこまで北や南には届かないため、枠はできるだけ近くに置きました。ここの地図はこのサイズのままです。
The map of {0} has not downloaded yet. It downloads by itself once this device is online.	{0}の地図はまだダウンロードされていません。端末がオンラインになると自動でダウンロードします。
The map of {0} is downloading. You can play here once it has.	{0}の地図をダウンロード中です。完了するとここで遊べます。
The morning and evening peaks run the same trains.	朝夕のラッシュは同じ本数の列車を運行します。
The motors of an electric train you follow, pulling away and braking, which the game makes to sound like these recordings of a 313 series train in Japan.	追従中の電車のモーター音（発進とブレーキ）で、ゲームが日本の313系電車の次の録音に似せて作っています。
The newest save could not be loaded. Continued from the save of {0}.	最新のセーブを読み込めませんでした。{0}のセーブから続けます。
The next stop is too far.	次の停車駅が遠すぎます。
The passengers each stretch of track carries each way in the chosen hour, against what its trains can carry: wider for more riders, darker blue for fuller trains, red when over capacity.	選んだ時間帯に各区間が各方向に運ぶ乗客数と、列車の輸送力の比較です。線が太いほど乗客が多く、青が濃いほど列車が混雑、赤は輸送力超過です。
The platforms of {0} and {1} are not on joined track	{0}と{1}のホームはつながった線路上にありません
The platforms of {0} and {1} are on tracks that do not meet, such as the two tracks of a double line with no crossover. Give both a platform on the same track, or select the track and tap Add X crossover.	{0}と{1}のホームは、渡り線のない複線の2本の線路のように、つながっていない線路上にあります。同じ線路に両方のホームを設けるか、線路を選んで「X形渡り線を追加」をタップしてください。
The rain, the typhoon’s wind and the thunder, which the game makes to sound like these recordings in Taipei and Tamsui.	雨、台風の風、雷の音で、ゲームが台北と淡水での次の録音に似せて作っています。
The real line bends too tightly here	実際の路線のカーブがきつすぎます
The real line turns back here	実際の路線はここでスイッチバック
The real line turns back here: trains reverse at this place, and one stretch of track cannot. Trace it as two stretches: first to the station where it turns back, then on from that station.	実際の路線はここでスイッチバックします：列車がここで向きを変えるため、1区間の線路では通れません。2区間に分けてトレースしてください：まず折り返す駅まで、次にその駅から先へ。
The real line turns too tightly here for the track (a curve of about {0} m; the tool lays {1} m or more).	ここは実際の路線のカーブがきつすぎます（半径約{0} m、このツールは{1} m以上で敷きます）。
The real railways are still loading.	実在の鉄道を読み込み中です。
The real railways on the map	地図上の実在の鉄道
The real times of TRA’s trains: every TRA train of a week on a real-world map and the next trains on its station cards, the Pingxi Line in the Real-World Demo, the Yilan Line in the TRA Demo, and the six branch lines you can buy on a real-world map.	台鉄の列車の実際の時刻：実在の地図での1週間分の台鉄全列車と駅カードの次発、実地図デモの平渓線、台鉄デモの宜蘭線、実在の地図で購入できる6支線。
The real-world data is not ready yet.	実地図データがまだ準備できていません。
The results are also sent with Report a Problem.	結果は「問題を報告」でも送信されます。
The richest picture; the phone may run hot and use more battery.	最も豊かな画面です。端末が熱くなり、電池を多く使うことがあります。
The riders each tile needs must be at least 1.	各区画に必要な利用者は1以上にしてください。
The road is built, along road already there: free.	既存の道路沿いに道路を敷きました：無料です。
The road is built, for {0}.	道路を敷きました（{0}）。
The road is built. It cost {0}; with unlimited funds nothing is paid.	道路を敷きました。費用は{0}ですが、資金無制限のため支払いはありません。
The road is taken up.	道路を撤去しました。
The road now costs {0}. Tap again to lay it.	道路の費用は現在{0}です。もう一度タップすると敷きます。
The roads could not be read for this part of the map.	地図のこの部分の道路を読み込めませんでした。
The roads haven't grown this far yet: a station road reaches at most 512 m.	道路はまだここまで伸びていません：駅前道路は最長512 mです。
The route menus are under Advanced in Lines.	経路メニューは「路線」の「詳細」にあります。
The same seed draws the same towns and events, so a map can be shared. Digits only, up to 10 of them.	同じシードなら同じ町とイベントになるので、地図を共有できます。数字のみ、最大10桁。
The save could not be read or written. Try again.	セーブデータを読み書きできませんでした。もう一度お試しください。
The screen's pace on this device lately:	この端末の最近の画面ペース：
The shape of Longshan Temple, Xingtian Temple, Zhinan Temple, six more of Taipei’s temples and a church in 3D maps, painted in the game’s colours.	3D地図の龍山寺、行天宮、指南宮など台北の寺廟9か所と教会1か所の形。ゲームの配色で塗っています。
The sidings cannot curve out from here: try the other side or fewer sidings.	ここからは留置線を分岐できません：反対側にするか、本数を減らしてください。
The sound of a train you follow, which the game makes to sound like these recordings: a KTX in Korea and two trains in Taiwan.	追従中の列車の走行音で、ゲームが次の録音に似せて作っています：韓国のKTXと台湾の2本の列車。
The souvenir shop is at its top level.	土産物店は最高レベルです。
The start and end are the same spot. Drag from here to another point.	始点と終点が同じ場所です。ここから別の地点へドラッグしてください。
The station has not been full often enough lately, so expanding would not carry more people.	最近この駅が満員になることが少ないため、拡張しても運べる人は増えません。
The station is already at its largest.	この駅はすでに最大規模です。
The station is at its largest.	駅は最大規模です。
The station master's reminders, goals met, holidays and typhoons are kept here.	駅長からのお知らせ、達成した目標、祝日、台風がここに記録されます。
The station's shops are at their top level.	この駅の店舗は最高レベルです。
The ten railway lines of Hong Kong’s MTR, from the Airport Express to the Disneyland Resort Line, each in its own colour, with their stations’ Chinese and English names. Their trains run to times estimated from how often and how fast the real trains ran on the days they were watched.	香港MTRの10路線（エアポート・エクスプレスからディズニーランド・リゾート線まで）を各路線の色で描き、駅名は中国語と英語です。列車は、観測した日の実際の列車の運転間隔と所要時間から推定した時刻で走ります。
The test game could not start.	テストゲームを開始できませんでした。
The textures of the 3D city’s walls, roofs, roads, pavements and grass.	3D都市の壁、屋根、道路、歩道、芝生のテクスチャ。
The theme and the departure melodies are original compositions for the game. The winter tune is the game’s own arrangement of Jingle Bells (James Lord Pierpont, 1857, in the public domain). The piano is the Salamander Grand Piano, the strings and harp are from VS Chamber Orchestra: Community Edition, and the other instruments are from GeneralUser GS.	テーマ曲と発車メロディはゲームのためのオリジナル曲です。冬の曲はゲーム独自の編曲による「Jingle Bells」（James Lord Pierpont、1857年、パブリックドメイン）です。ピアノはSalamander Grand Piano、弦楽器とハープはVS Chamber Orchestra: Community Edition、その他の楽器はGeneralUser GSを使用しています。
The top of the railway world.	鉄道界の頂点です。
The town builds on zones near a busy station, one cell a day.	利用者の多い駅の近くの用途地域に、都市が1日1マスずつ建てます。
The town has enough of this for now: it builds when demand comes back.	都市には今これが十分あります：需要が戻ると建ちます。
The town has put up its first building on land you zoned: {0}.	あなたが指定した用途地域に、都市が最初の建物を建てました：{0}。
